const now = new Date();
const currentMonth = now.getMonth();
const year = now.getFullYear();

const arabicMonths = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];

function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

let quarter, quarterArabic, startMonth, endMonth, reportYear;

if (currentMonth === 0) { quarter = 4; quarterArabic = 'الرابع'; startMonth = 9; endMonth = 11; reportYear = year - 1; }
else if (currentMonth === 3) { quarter = 1; quarterArabic = 'الأول'; startMonth = 0; endMonth = 2; reportYear = year; }
else if (currentMonth === 6) { quarter = 2; quarterArabic = 'الثاني'; startMonth = 3; endMonth = 5; reportYear = year; }
else if (currentMonth === 9) { quarter = 3; quarterArabic = 'الثالث'; startMonth = 6; endMonth = 8; reportYear = year; }
else { quarter = Math.ceil((currentMonth + 1) / 3); quarterArabic = ['الأول', 'الثاني', 'الثالث', 'الرابع'][quarter - 1]; startMonth = (quarter - 1) * 3; endMonth = startMonth + 2; reportYear = year; }

const startDate = `${reportYear}-${String(startMonth + 1).padStart(2, '0')}-01`;
const endDate = new Date(reportYear, endMonth + 1, 0).toISOString().split('T')[0];
const fileName = `تقرير_ربع_سنوي_${reportYear}-Q${quarter}.docx`;

return {
  json: {
    quarter: quarter,
    quarter_arabic: quarterArabic,
    year: reportYear,
    year_arabic: toArabicNumerals(reportYear),
    start_month: arabicMonths[startMonth],
    end_month: arabicMonths[endMonth],
    start_date: startDate,
    end_date: endDate,
    file_name: fileName,
    report_title: `التقرير الربع سنوي الشامل - الربع ${quarterArabic} ${toArabicNumerals(reportYear)}`,
    previous_year: reportYear - 1
  }
};

const criminology = $('Scholar - Criminology').item?.json?.organic_results || [];
const cyber = $('Scholar - Cybercrime').item?.json?.organic_results || [];
const allStudies = [...criminology, ...cyber];

const seen = new Set();
const uniqueStudies = allStudies.filter(s => {
  const key = s.title?.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).slice(0, 30);

return {
  json: {
    studies_count: uniqueStudies.length,
    studies: uniqueStudies.map((s, i) => ({
      index: i + 1,
      title: s.title,
      authors: s.publication_info?.authors || 'Unknown',
      source: s.publication_info?.summary || s.source,
      link: s.link,
      snippet: s.snippet,
      cited_by: s.inline_links?.cited_by?.total || 0
    }))
  }
};

