const quarterVars = $('Set Quarter Variables').item.json;
const executiveSummary = $('Perplexity - Executive Summary').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const statistics = $('Perplexity - Crime Statistics').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const comparison = $('Perplexity - YoY Comparison').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const literature = $('Perplexity - Literature Review').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const recommendations = $('Perplexity - Recommendations').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const studiesCount = $('Merge Studies').item?.json?.studies_count || 0;

const report = `
═══════════════════════════════════════════════════════════════
التقرير الربع سنوي الشامل
───────────────────────────────────────────────────────────────
الربع ${quarterVars.quarter_arabic} - ${quarterVars.year_arabic}
الفترة: ${quarterVars.start_month} إلى ${quarterVars.end_month} ${quarterVars.year_arabic}
═══════════════════════════════════════════════════════════════

المحتويات:
─────────
١. الملخص التنفيذي
٢. الإحصائيات التفصيلية لجميع أنواع الجرائم
٣. المقارنة مع نفس الربع من العام السابق
٤. مراجعة الأدبيات العلمية (${studiesCount} دراسة)
٥. التوصيات القائمة على الأدلة
٦. المراجع والمصادر

═══════════════════════════════════════════════════════════════
١. الملخص التنفيذي
═══════════════════════════════════════════════════════════════
${executiveSummary}

═══════════════════════════════════════════════════════════════
٢. الإحصائيات التفصيلية لجميع أنواع الجرائم
═══════════════════════════════════════════════════════════════
${statistics}

═══════════════════════════════════════════════════════════════
٣. المقارنة مع نفس الربع من العام السابق
═══════════════════════════════════════════════════════════════
${comparison}

═══════════════════════════════════════════════════════════════
٤. مراجعة الأدبيات العلمية
═══════════════════════════════════════════════════════════════
عدد الدراسات المراجعة: ${studiesCount}

${literature}

═══════════════════════════════════════════════════════════════
٥. التوصيات القائمة على الأدلة
═══════════════════════════════════════════════════════════════
${recommendations}

═══════════════════════════════════════════════════════════════
٦. المراجع والمصادر
═══════════════════════════════════════════════════════════════
المراجع متوفرة في نظام قاعدة البيانات المرجعية

───────────────────────────────────────────────────────────────
نهاية التقرير
───────────────────────────────────────────────────────────────
`;

return { json: { report_content: report, report_title: quarterVars.report_title, file_name: quarterVars.file_name, quarter: quarterVars.quarter_arabic, year: quarterVars.year } };

